import { action } from '@storybook/addon-actions';
import { ProcessModalComponent } from '../../../../index';
const meta = {
    title: '浮層元件/Process Modal',
    id: 'process-modal',
    component: ProcessModalComponent,
    tags: ['autodocs'],
    argTypes: {
        type: {
            description: '彈窗類型：running（處理中）/ congratulation（完成慶祝）',
            control: { type: 'select' },
            options: ['running', 'congratulation'],
            table: { defaultValue: { summary: 'running' } },
        },
        message: {
            description: '顯示於彈窗內的提示訊息',
            control: { type: 'text' },
        },
        isOpen: {
            description: '控制彈窗開閉',
            control: { type: 'boolean' },
            table: { defaultValue: { summary: 'false' } },
        },
        dismissed: {
            description: '點擊 backdrop 關閉時觸發（僅 congratulation 類型可關閉）',
            action: 'dismissed',
        },
    },
    args: {
        type: 'running',
        message: '資料處理中…',
        isOpen: false,
    },
};
export default meta;
export const RunningOpen = {
    name: '處理中（開啟）',
    args: {
        isOpen: true,
        type: 'running',
        message: '資料處理中，請稍候，請勿關閉視窗...',
    },
};
export const CongratulationOpen = {
    name: '完成慶祝（開啟）',
    args: {
        isOpen: true,
        type: 'congratulation',
        message: '恭喜！申請已全部完成，感謝您的努力！',
    },
};
export const Closed = {
    name: '關閉狀態',
    args: {
        isOpen: false,
        type: 'running',
        message: '此彈窗目前為關閉狀態',
    },
};
export const Interactive = {
    name: '互動示範',
    render: () => ({
        template: `
      <div style="padding:16px;">
        <p style="font-size:13px;color:#686868;margin-bottom:12px;">
          點擊按鈕開啟不同類型的彈窗。Congratulation 類型可點擊 backdrop 關閉。
        </p>
        <div style="display:flex;gap:12px;flex-wrap:wrap;">
          <button
            (click)="openRunning()"
            style="padding:8px 16px;background:#4ba5b2;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:14px;"
          >
            開啟「處理中」
          </button>
          <button
            (click)="openCongrats()"
            style="padding:8px 16px;background:#5da26b;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:14px;"
          >
            開啟「完成慶祝」
          </button>
        </div>
        <app-process-modal
          [type]="type"
          [message]="message"
          [isOpen]="isOpen"
          (dismissed)="onDismissed()"
        ></app-process-modal>
      </div>
    `,
        props: {
            type: 'running',
            message: '',
            isOpen: false,
            openRunning() {
                this.type = 'running';
                this.message = '資料處理中，請稍候，請勿關閉視窗...';
                this.isOpen = true;
                setTimeout(() => { this.isOpen = false; }, 3000);
            },
            openCongrats() {
                this.type = 'congratulation';
                this.message = '恭喜！申請已全部完成，感謝您的努力！';
                this.isOpen = true;
            },
            onDismissed() {
                this.isOpen = false;
                action('dismissed')();
            },
        },
        moduleMetadata: { imports: [ProcessModalComponent] },
    }),
};
